const USER_ID = "zealt-user01";
const OUTPUT_PATH = "/home/user/schema.json";

const findSlackPostMessageTool = (tools: Array<Record<string, unknown>>) => {
  return tools.find((tool) => {
    const name = typeof tool.name === "string" ? tool.name.toLowerCase() : "";
    const slug = typeof tool.slug === "string" ? tool.slug.toLowerCase() : "";
    const app = typeof tool.app === "string" ? tool.app.toLowerCase() : "";
    const action = typeof tool.action === "string" ? tool.action.toLowerCase() : "";

    return (
      name === "slack_chat_post_message" ||
      slug === "slack_chat_post_message" ||
      (app === "slack" && action === "chat_post_message")
    );
  });
};

const main = async () => {
  const composio = new Composio();
  const modifier = new SchemaModifier().hide("slack", "chat_post_message", ["text"]);
  const session = await composio.create(USER_ID, { modifiers: [modifier] });

  const tools = await session.getTools();
  const slackTool = findSlackPostMessageTool(tools as Array<Record<string, unknown>>);

  if (!slackTool || typeof slackTool.inputSchema !== "object") {
    throw new Error("Could not find Slack chat_post_message tool or its input schema.");
  }

  writeFileSync(OUTPUT_PATH, JSON.stringify(slackTool.inputSchema, null, 2));
};

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

