import { writeFileSync } from "node:fs";

type SchemaModifierRule = {
  toolkit: string;
  action: string;
  fields: string[];
};

class SchemaModifier {
  private rules: SchemaModifierRule[] = [];

  hide(toolkit: string, action: string, fields: string[]) {
    this.rules.push({ toolkit: toolkit.toLowerCase(), action: action.toLowerCase(), fields });
    return this;
  }

  modifySchema = ({
    toolSlug,
    toolkitSlug,
    schema,
  }: {
    toolSlug: string;
    toolkitSlug: string;
    schema: Record<string, any>;
  }) => {
    const matchingRule = this.rules.find(
      (rule) =>
        rule.toolkit === toolkitSlug.toLowerCase() &&
        toolSlug.toLowerCase() === `${rule.toolkit}_${rule.action}`,
    );

    if (!matchingRule || !schema?.inputParameters?.properties) {
      return schema;
    }

    const properties = { ...schema.inputParameters.properties } as Record<string, unknown>;
    matchingRule.fields.forEach((field) => {
      delete properties[field];
    });

    const required = Array.isArray(schema.inputParameters.required)
      ? schema.inputParameters.required.filter(
          (field: string) => !matchingRule.fields.includes(field),
        )
      : schema.inputParameters.required;

    return {
      ...schema,
      inputParameters: {
        ...schema.inputParameters,
        properties,
        required,
      },
    };
  };
}

const USER_ID = "zealt-user01";
const OUTPUT_PATH = "/home/user/schema.json";

const findSlackPostMessageTool = (tools: Array<Record<string, any>>) => {
  return tools.find((tool) => {
    const name =
      typeof tool?.function?.name === "string"
        ? tool.function.name.toLowerCase()
        : typeof tool.name === "string"
          ? tool.name.toLowerCase()
          : "";

    return name === "slack_chat_post_message";
  });
};

const extractSchema = (tool: Record<string, any>) => {
  return (
    tool?.function?.parameters ??
    tool?.inputParameters ??
    tool?.inputSchema ??
    tool?.schema?.inputParameters
  );
};

const main = async () => {
  const composio = new Composio();
  const modifier = new SchemaModifier().hide("slack", "chat_post_message", ["text"]);
  const session = await composio.create(USER_ID);

  const tools = await session.tools({ modifySchema: modifier.modifySchema });
  const slackTool = findSlackPostMessageTool(tools as Array<Record<string, any>>);

  if (!slackTool) {
    throw new Error("Could not find Slack chat_post_message tool in session tools.");
  }

  const schema = extractSchema(slackTool);
  if (!schema) {
    throw new Error("Slack tool schema not found after modification.");
  }

  writeFileSync(OUTPUT_PATH, JSON.stringify(schema, null, 2));
};

