  const modifier = new SchemaModifier().hide("slack", "chat_post_message", ["text"]);
  const session = await composio.create(USER_ID, {
    toolkits: { enable: ["slack"] },
  });

  const tools = await session.tools({ modifySchema: modifier.modifySchema });
  const slackTool = findSlackPostMessageTool(tools as Array<Record<string, any>>);

  if (!slackTool) {
    const toolEntries = Array.isArray(tools) ? (tools as Array<any>) : [];
    const toolNames = toolEntries
      .map((tool) => tool?.function?.name ?? tool?.name ?? tool?.slug)
      .filter(Boolean)
      .slice(0, 20);
    throw new Error(
      `Could not find Slack chat_post_message tool in session tools. Sample tools: ${toolNames.join(", ")}`,
    );
  }

  const schema = extractSchema(slackTool);
  if (!schema) {
    throw new Error("Slack tool schema not found after modification.");
  }

  writeFileSync(OUTPUT_PATH, JSON.stringify(schema, null, 2));
};

